import 'package:flutter/widgets.dart';

class LayersExample extends StatefulWidget {
  const LayersExample();
  @override
  State<LayersExample> createState() => _LayersExampleState();
}

class _LayersExampleState extends State<LayersExample> {
  int _width = @@_width@@;
  @override
  Widget build(BuildContext context) => SizedBox(
    width: _width.toDouble(),
    child: LayoutBuilder(
      builder: (BuildContext context, BoxConstraints constraints) {
        final CarbonBreakpoint breakpoint = CarbonBreakpoint.of(
          constraints.maxWidth,
        );
        Widget layer(BuildContext context, String label, Widget? child) =>
            ColoredBox(
              color: CarbonLayer.of(context).layer,
              child: Padding(
                padding: const EdgeInsets.all(12),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  mainAxisSize: MainAxisSize.min,
                  children: <Widget>[
                    CarbonText('$label: level ${CarbonLayer.levelOf(context)}'),
                    CarbonTextInput(labelText: '$label field'),
                    ?child,
                  ],
                ),
              ),
            );
        return Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: <Widget>[
            CarbonText(
              '${constraints.maxWidth.round()}px → ${breakpoint.name}, ${breakpoint.columns} columns',
            ),
            CarbonLayer(
              level: 0,
              child: Builder(
                builder: (BuildContext context) => layer(
                  context,
                  'Root',
                  CarbonLayer(
                    child: Builder(
                      builder: (BuildContext context) => layer(
                        context,
                        'Nested',
                        CarbonLayer(
                          child: Builder(
                            builder: (BuildContext context) =>
                                layer(context, 'Deep', null),
                          ),
                        ),
                      ),
                    ),
                  ),
                ),
              ),
            ),
          ],
        );
      },
    ),
  );
}
''');
  }
}

